function calculateBreakeven() {
  const machineCost = parseFloat(document.getElementById('machineCost').value) || 0;
  const dailyFrequency = parseFloat(document.getElementById('dailyFrequency').value) || 0;
  const handwashCost = parseFloat(document.getElementById('handwashCost').value) || 0;
  const dishwasherCost = parseFloat(document.getElementById('dishwasherCost').value) || 0;
  const handwashTime = parseFloat(document.getElementById('handwashTime').value) || 0;
  const dishwasherTime = parseFloat(document.getElementById('dishwasherTime').value) || 0;
  const hourlyWage = parseFloat(document.getElementById('hourlyWage').value) || 0;

  const utilitySavingPerRun = handwashCost - dishwasherCost;
  const utilitySavingPerYear = utilitySavingPerRun * dailyFrequency * 365;

  const timeSavedPerRunMin = handwashTime - dishwasherTime;
  const timeSavedPerYearMin = timeSavedPerRunMin * dailyFrequency * 365;
  const timeSavedPerYearHours = timeSavedPerYearMin / 60;
  const timeValuePerYear = timeSavedPerYearHours * hourlyWage;

  const totalBenefitPerYear = utilitySavingPerYear + timeValuePerYear;

  let yearsTotal = totalBenefitPerYear > 0 ? (machineCost / totalBenefitPerYear) : Infinity;
  let yearsUtility = utilitySavingPerYear > 0 ? (machineCost / utilitySavingPerYear) : Infinity;

  let headlineText = '';
  if (yearsTotal === Infinity || yearsTotal <= 0) {
    headlineText = '現在の設定では回収が難しい条件です。';
  } else {
    const yearsDisplay = yearsTotal < 1 ? (Math.round(yearsTotal * 12) + 'ヶ月') : (yearsTotal.toFixed(1) + '年');
    headlineText = `約<strong>${yearsDisplay}</strong>で本体代金の元が取れます！`;
  }

  const resultContainer = document.getElementById('calcResult');
  resultContainer.innerHTML = `
    <div class="result-headline">結論：${headlineText}</div>
    <div class="metrics-row">
      <div class="metric-card">
        <span>年間節約額（水道光熱費）</span>
        <strong>${Math.round(utilitySavingPerYear).toLocaleString()} 円</strong>
        <small>水・ガス・電気・洗剤の年間差額</small>
      </div>
      <div class="metric-card">
        <span>年間生み出す自由時間</span>
        <strong>${Math.round(timeSavedPerYearHours)} 時間</strong>
        <small>1日あたり約${Math.round(timeSavedPerRunMin * dailyFrequency)}分の時短</small>
      </div>
      <div class="metric-card">
        <span>時間価値を含めた年間節約</span>
        <strong>${Math.round(totalBenefitPerYear).toLocaleString()} 円</strong>
        <small>時給${hourlyWage.toLocaleString()}円換算</small>
      </div>
      <div class="metric-card">
        <span>光熱費のみでの回収期間</span>
        <strong>${yearsUtility !== Infinity && yearsUtility > 0 ? yearsUtility.toFixed(1) + '年' : '回収不可'}</strong>
        <small>時間価値を含めない場合</small>
      </div>
    </div>
  `;
}

document.addEventListener('DOMContentLoaded', calculateBreakeven);
